/** Best site logo for a hostname: exact host, else registered-domain suffix. */
function glyphForHost(hostname: string): SiteGlyphData | undefined {
  const h = hostname.toLowerCase().replace(/^www./, '')
  const direct = HOST_SLUG[h]
  if (direct !== undefined) return GLYPHS[direct]
  if (h.endsWith('.atlassian.net')) return GLYPHS.jira
  return undefined
}

/** Resolve the offline brand glyph for an entry (url first, ssh host second). */
export function siteGlyph(url?: string, sshHost?: string): SiteGlyphData | undefined {
  const raw = url && url.trim().length > 0 ? url.trim() : sshHost
  if (!raw) return undefined
  let candidate = raw
  if (!/^[a-z]+:\/\//i.test(candidate)) candidate = 'https://' + candidate
  try {
    const host = new URL(candidate).hostname
    return glyphForHost(host)
  } catch {
    return undefined
  }
}
